6	const TYPE_THRESHOLD = 3;
7	
8	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
9	
10	const countDistinctTypes = (army: Card[]): number =>
11	  new Set(army.map((card) => `${card.monster}:${card.rank}`)).size;
12	
13	const pointsPerSphinxFor = (typeCount: number): number =>
14	  typeCount > TYPE_THRESHOLD ? 2 * (typeCount - TYPE_THRESHOLD) : 1;
15	
16	export const scoreArmy = (army: Card[]): number =>
17	  army.filter(isSphinx).length * pointsPerSphinxFor(countDistinctTypes(army));
